mapper.select:
SELECT h.id AS recordId, h.batch_id AS batchId, b.batch_name AS batchName, h.user_id AS userId, u.real_name AS userName, u.phone AS userPhone, NULL AS ruleId, NULL AS ruleName, h.total_score AS ruleScore, 'admin_inspection' AS sourceType, h.inspector_id AS inspectorId, i.real_name AS inspectorName, b.inspection_date AS inspectionDate, h.remark AS description, NULL AS images, 'approved' AS status, h.create_time AS createTime FROM inspection_household h LEFT JOIN `user` u ON h.user_id = u.id LEFT JOIN `user` i ON h.inspector_id = i.id LEFT JOIN inspection_batch b ON h.batch_id = b.id
h.deleted = 0
AND h.batch_id = #{query.batchId}
AND h.user_id = #{query.userId}
AND h.create_time >= #{query.startDate}
AND h.create_time <= #{query.endDate}
ORDER BY h.create_time DESC

SELECT b.batch_name AS batchName, a.inspection_date AS inspectionDate, u.real_name AS userName, r.rule_name AS ruleName, r.points AS score, u2.real_name AS inspectorName, a.description, a.create_time AS createTime FROM points_apply a LEFT JOIN `user` u ON a.user_id = u.id LEFT JOIN points_rule r ON a.rule_id = r.id LEFT JOIN `user` u2 ON a.inspector_id = u2.id LEFT JOIN inspection_batch b ON a.inspection_batch_id = b.id
a.source_type = 'admin_inspection'
AND a.inspection_batch_id = #{query.batchId}
AND a.user_id = #{query.userId}
AND a.inspection_date >= #{query.startDate}
AND a.inspection_date <= #{query.endDate}
ORDER BY a.create_time DESC
